		tax = income * 0.30 // 30% for income above 50,000 (buggy)
	}

	// The 'year' parameter is currently unused but kept for future expansion
	// or to satisfy the "leap year handling" hint, if it were to be implemented.
	_ = year

	return tax, nil
}

